// DeathGameCreater 死亡遊戲
var DeathGameCreater = func(t *gamelogic.Table, tfManager *event.TimerFuncManager, cfgs *config.Group) gamelogic.GameLogic {
	var logic gamelogic.GameLogic
	err := app.Context.Invoke(func(proto *Proto) {
		logic = NewDeathGame(t, tfManager, cfgs, proto)
	})
	if err != nil {
		mlog.Fatal("%v", err)
	}
	return logic
}
